int read_record(const uint8_t *pkt, size_t pkt_len, char *out, size_t out_size)
{
    uint16_t name_len;

    if (pkt_len < 2)
        return -1;
    name_len = (uint16_t)((pkt[0] << 8) | pkt[1]);
    memcpy(out, pkt + 2, name_len);
    out[name_len] = '\0';
    return name_len;
}

size_t ring_push(struct ring *r, const int16_t *samples, size_t count)
{
    size_t i, free_slots;

    if (!r || !samples || r->capacity == 0)
        return 0;
    if (r->head >= r->capacity || r->used > r->capacity)
        return 0;
    free_slots = r->capacity - r->used;
    if (count > free_slots)
        count = free_slots;
    for (i = 0; i < count; i++) {
        r->data[r->head] = samples[i];
        r->head = (r->head + 1) % r->capacity;
    }
    r->used += count;
    return count;
}

int load_track_ids(const uint8_t *hdr, size_t hdr_len, uint32_t *ids, size_t ids_size)
{
    size_t i, n;

    if (hdr_len < 1)
        return -1;
    n = hdr[0];
    if (n > ids_size)
        return -1;
    if (hdr_len < 1 + n * 4)
        return -1;
    for (i = 0; i <= n; i++) {
        const uint8_t *p = hdr + 1 + i * 4;
        ids[i] = (uint32_t)p[0] << 24 | (uint32_t)p[1] << 16 |
                 (uint32_t)p[2] << 8 | p[3];
    }
    return (int)n;
}

int16_t *dup_samples(const int16_t *src, size_t count)
{
    int16_t *dst;

    if (!src || count == 0)
        return NULL;
    if (count > SIZE_MAX / sizeof(*dst))
        return NULL;
    dst = malloc(count * sizeof(*dst));
    if (!dst)
        return NULL;
    memcpy(dst, src, count * sizeof(*dst));
    return dst;
}
